<template><div class="guide"><section class="guide-hero"><div><p class="eyebrow">AI SHOPPING GUIDE</p><h1>把需求交给我，帮你选得更合适</h1><p>我会结合你的预算、用途、商品库存、价格优惠和历史偏好，生成可以直接购买的推荐清单。</p></div><div class="signals"><span>● 理解需求</span><span>● 实时查价</span><span>● 库存校验</span><span>● 推荐解释</span></div></section><el-row :gutter="18" class="workspace"><el-col :xs="24" :lg="8"><section class="panel input-panel"><p class="step">STEP 01</p><el-tag type="success">AI 在线</el-tag><h2>告诉我你想买什么</h2><div class="chips"><button @click="quick('5000 元左右的轻薄办公本')">5000 元左右的轻薄办公本</button><button @click="quick('适合送父母的健康家电')">适合送父母的健康家电</button><button @click="quick('通勤用的降噪蓝牙耳机')">通勤用的降噪蓝牙耳机</button></div><el-input v-model="question" type="textarea" :rows="7" maxlength="500" show-word-limit placeholder="例如：想买一台适合大学生写代码和做毕设的笔记本，预算 5000 左右，希望轻薄、续航好……" /><el-button class="generate" type="primary" :loading="loading" @click="send">生成智能推荐</el-button><p class="hint">推荐过程会读取你的收藏与购物偏好，仅用于本次导购分析</p></section></el-col><el-col :xs="24" :lg="16"><section class="panel result-panel"><div class="result-head"><div><p class="step">STEP 02</p><h2>AI 推荐结果</h2></div><el-tag v-if="recommendations.length" type="success">已完成</el-tag></div><div v-if="messages.length" class="answer">{{ messages[messages.length-1].content }}</div><div v-for="(r,i) in recommendations" :key="r.id" class="recommend"><div class="rank">TOP {{ i + 1 }}</div><el-image :src="r.productImage" fit="cover" /><div class="recommend-main"><h3>{{ r.productName }}</h3><p>{{ r.reason }}</p><small>商品状态：在售　当前价格：¥{{ r.priceSnapshot }}　库存数量：{{ r.stockSnapshot }}</small><strong>¥{{ r.priceSnapshot }}</strong></div><el-button type="primary" size="small" @click="addToCart(r)">加入购物车</el-button></div><el-empty v-if="!recommendations.length" description="输入你的预算、用途或偏好，开始生成推荐" /></section></el-col></el-row><section v-if="steps.length" class="panel timeline"><h2>Agent 执行时间线</h2><el-timeline><el-timeline-item v-for="s in steps" :key="s.id" :timestamp="'Step ' + s.seq"><b>{{ s.toolName }}</b><p>{{ s.status }} · {{ s.costMs || 0 }}ms</p></el-timeline-item></el-timeline></section></div></template>
<script setup>
import { ref,onMounted } from 'vue';import { useRoute } from 'vue-router';import { ElMessage } from 'element-plus';import request from '../../api/request'
const route=useRoute();const question=ref('');const messages=ref([]);const steps=ref([]);const recommendations=ref([]);const loading=ref(false);onMounted(()=>{if(route.query.productId)question.value=`帮我介绍一下这个商品（ID:${route.query.productId}）的优缺点`})
async function send(){if(loading.value)return;if(!question.value.trim())return ElMessage.warning('请输入你的购买需求');const q=question.value.trim();const history=messages.value.slice(-10).map(({role,content})=>({role,content}));messages.value.push({role:'user',content:q});question.value='';loading.value=true;try{const data=await request.post('/ai/guide',{question:q,history});messages.value.push({role:'assistant',content:data.answer||'暂时没有生成推荐'});const run=await request.get(`/ai/agent/runs/${data.runId}`);steps.value=run?.steps||[];recommendations.value=await request.get(`/ai/guide/${data.taskId}/recommendations`)}catch{messages.value.pop();ElMessage.error('导购服务暂时不可用，请稍后重试')}finally{loading.value=false}}
function quick(t){if(loading.value)return;question.value=t;send()}async function addToCart(r){await request.post('/cart',{productId:r.productId,quantity:1});ElMessage.success('已加入购物车')}
</script>
<style scoped>
.guide{max-width:1420px;margin:auto}.guide-hero{background:linear-gradient(110deg,#061b2a,#1a5664);border-radius:16px;padding:40px 48px;color:#fff;display:flex;justify-content:space-between;align-items:center}.eyebrow,.step{font-size:12px;letter-spacing:2px;color:#59d5e3;font-weight:800}.guide-hero h1{font-size:34px;margin:18px 0 12px}.guide-hero p:not(.eyebrow){color:#b5d1d7}.signals{display:grid;grid-template-columns:1fr 1fr;gap:12px}.signals span{padding:13px 20px;border:1px solid #39717b;background:#ffffff12;border-radius:12px;color:#c8e9ed;font-size:13px}.workspace{margin-top:18px}.panel{background:#fff;border:1px solid #e1ebf0;border-radius:14px;padding:26px}.input-panel{position:relative}.input-panel>.el-tag{position:absolute;right:26px;top:28px}.panel h2{font-size:23px;margin:10px 0 20px}.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.chips button{border:1px solid #dce8ed;background:#f7fafb;color:#607b8b;padding:8px 11px;border-radius:18px;font-size:12px;cursor:pointer}.generate{width:100%;height:48px;margin-top:16px;border-radius:10px;font-size:15px;font-weight:700}.hint{text-align:center;color:#a1b0b8;font-size:12px}.result-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid #edf1f3}.result-head h2{margin-bottom:18px}.answer{background:#edf9f8;color:#315f68;padding:14px;border-radius:10px;line-height:1.7;margin:18px 0}.recommend{display:flex;align-items:center;gap:14px;border:1px solid #e2eaee;border-radius:12px;padding:12px;margin-top:14px;position:relative}.recommend> .el-image{width:112px;height:92px;border-radius:9px;flex:none}.rank{position:absolute;left:12px;top:12px;background:#159fba;color:#fff;border-radius:4px;padding:3px 7px;font-size:10px}.recommend-main{flex:1;min-width:0}.recommend-main h3{margin:0 0 6px;font-size:17px}.recommend-main p{margin:0 0 8px;color:#667f8e;font-size:13px;line-height:1.5}.recommend-main small{display:block;color:#8ca0ad}.recommend-main strong{display:block;color:#ff604f;font-size:21px;margin-top:7px}.timeline{margin-top:18px}.timeline p{color:#8295a1;font-size:12px}
</style>
